      pIVar2 = this->leftHand;
      if ((pIVar2->m_frameFlags & 0x20) == 0) {
        I3D_frame::UpdateWMatrixProc(pIVar2);
      }
      pSVar4 = S_vector::OperatorMul
                         ((S_vector *)&this->leftHandOffset,local_20,&pIVar2->m_worldMatrix);
      handTarget->x = pSVar4->x;
      (this->leftHandTarget).y = pSVar4->y;
      (this->leftHandTarget).z = pSVar4->z;
      (this->leftHandTarget).w = pSVar4[1].x;
      if ((int)this->hand < 0) {
        pIVar2 = this->leftGrip;
        if (this->stock == (I3D_frame *)0x0) {
          if ((pIVar2->m_frameFlags & 0x20) == 0) {
            I3D_frame::UpdateWMatrixProc(pIVar2);
          }
          pSVar4 = (S_vector *)0x0;
        }
        else {
          local_20[0].x = 0.0;
          local_20[0].y = -1.0;
          local_20[0].z = 0.0;
          if ((pIVar2->m_frameFlags & 0x20) == 0) {
            I3D_frame::UpdateWMatrixProc(pIVar2);
          }
          pSVar4 = local_20;
        }
        ReachArm(this,0x11,0x13,(S_vector *)((pIVar2->m_worldMatrix).m + 3),handTarget,
                 this->leftHand,this->support,pSVar4);
      }
      if (this->stock != (I3D_frame *)0x0) {
        pIVar2 = this->rightGrip;
        if ((pIVar2->m_frameFlags & 0x20) == 0) {
          I3D_frame::UpdateWMatrixProc(pIVar2);
        }
        ReachArm(this,0x10,0x12,(S_vector *)((pIVar2->m_worldMatrix).m + 3),pSVar1,this->rightHand,
                 1.0,(S_vector *)0x0);
      }
    }
  }
  return;
